/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Array, MutableDenseNDimArray, PartialDerivative, Sym, Tensor, TensorHead, TensorIndex, TensorIndexType, TensorSymmetry, fn, log, mul, pow, rational, symbols } from '../../src';
import { at, sympyStr } from '../sympy-str';

describe("doctests of sympy.tensor.toperators", () => {
  it("expr.get_indices()", () => {
    const dim_L = new Sym('dim_L');
    const v1 = TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true);
    expect(sympyStr([v1, at(PartialDerivative(new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [v1]), new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('j', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])).getIndices(), 1)])).toBe('[i, -j]');
  });
  it("expr.get_indices() (2)", () => {
    const dim_L = new Sym('dim_L');
    const v1 = PartialDerivative(new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('L_0', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('L_0', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])).getIndices();
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[L_0, -L_0]');
  });
  it("expr.get_free_indices()", () => {
    expect(sympyStr([])).toBe('[]');
  });
  it("expr.get_indices() (3)", () => {
    const dim_L = new Sym('dim_L');
    const v1 = TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true);
    const v2 = PartialDerivative(new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [v1]), new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('j', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('k', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])).getIndices();
    expect(sympyStr([v1, at(v2, 1), at(v2, 2)])).toBe('[i, -j, -k]');
  });
  it("expr.get_free_indices() (2)", () => {
    const dim_L = new Sym('dim_L');
    const v1 = TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true);
    expect(sympyStr([v1, at(PartialDerivative(new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [v1]), new Tensor(TensorHead('B', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('j', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])).getFreeIndices(), 1)])).toBe('[i, -j]');
  });
  it("Array(compA).diff(Array(compB))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(Array([fn('sin', [x]), mul(pow(y, 3), log(x))], [2]).diff(Array([x, y], [2])))).toBe('[[cos(x), y**3/x], [0, 3*y**2*log(x)]]');
  });
  it("expr", () => {
    const dim_L = new Sym('dim_L');
    expect(sympyStr(PartialDerivative(new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('j', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])))).toBe('PartialDerivative(A(i), A(j))');
  });
  it("expr (2)", () => {
    const dim_L = new Sym('dim_L');
    expect(sympyStr(PartialDerivative(new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])))).toBe('PartialDerivative(A(L_0), A(L_0))');
  });
  it("expr (3)", () => {
    const dim_L = new Sym('dim_L');
    expect(sympyStr(PartialDerivative(PartialDerivative(new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('j', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])), new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('k', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])))).toBe('PartialDerivative(A(i), A(j), A(k))');
  });
  it("expr.replace_with_arrays({A(i): compA, B(i): compB})", () => {
    const [dim_L, x, y] = symbols('dim_L x y');
    expect(sympyStr(PartialDerivative(new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), new Tensor(TensorHead('B', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('j', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])).replaceWithArrays(new Map([[new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), [fn('sin', [x]), mul(pow(y, 3), log(x))]], [new Tensor(TensorHead('B', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), [x, y]]])))).toBe('[[cos(x), 0], [y**3/x, 3*y**2*log(x)]]');
  });
  it("Matrix(compA).diff(Matrix(compB)).reshape(2, 2)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(MutableDenseNDimArray([fn('cos', [x]), mul(pow(x, -1), pow(y, 3)), rational(0), mul(3, pow(y, 2), log(x))], [2, 1, 2, 1]).reshape(2, 2))).toBe('[[cos(x), y**3/x], [0, 3*y**2*log(x)]]');
  });
  it("expr.replace_with_arrays({A(i): compA, B(i): compB}, [-j, i])", () => {
    const [dim_L, x, y, j, i] = symbols('dim_L x y j i');
    expect(sympyStr(PartialDerivative(new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), new Tensor(TensorHead('B', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('j', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)])).replaceWithArrays(new Map([[new Tensor(TensorHead('A', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), [fn('sin', [x]), mul(pow(y, 3), log(x))]], [new Tensor(TensorHead('B', [TensorIndexType('L', { dim: dim_L, dummyName: 'L' })], new TensorSymmetry(1, 0)), [TensorIndex('i', TensorIndexType('L', { dim: dim_L, dummyName: 'L' }), true)]), [x, y]]]), [mul(-1, j), i]))).toBe('[[cos(x), y**3/x], [0, 3*y**2*log(x)]]');
  });
});
